mapper.insert:
INSERT INTO document_upload_outbox_event (
    event_code, task_code, status, publishing_token, publishing_lease_until, failure_reason, created_at, updated_at
) VALUES (
    #{eventCode}, #{taskCode}, #{status}, #{publishingToken}, #{publishingLeaseUntil}, #{failureReason}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT id, event_code, task_code, status, publishing_token, publishing_lease_until, failure_reason, created_at, updated_at
FROM document_upload_outbox_event
WHERE status = 2
  AND publishing_lease_until <= #{now}
ORDER BY publishing_lease_until ASC
LIMIT #{limit}

mapper.update:
UPDATE document_upload_outbox_event
SET status = 0,
    publishing_token = NULL,
    publishing_lease_until = NULL,
    failure_reason = #{failureReason},
    updated_at = #{now}
WHERE event_code = #{eventCode}
  AND status = 2
  AND publishing_lease_until <= #{now}
